import concurrent.futures,hashlib,json,os,subprocess,sys
from datetime import datetime,timezone
from pathlib import Path
sys.path.insert(0,str(Path.cwd()/'src'))
from proworksim.audit import code_identity
PYTHON=str(Path.cwd()/'.venv/bin/python')
JOBS={
 'A1':['scripts/model_development_experiment.py','--protocol','examples/model-v11/development-protocol.json','--output','runs/model-api-v11-development','--workers','6'],
 'B':['scripts/executable_project_experiment.py','--output','runs/executable-projects-v11-final','--workers','3'],
 'conditions':['scripts/condition_scope_experiment_v011.py','--output','runs/condition-scope-v011-final'],
 'episode':['scripts/episode_boundary_experiment_v011.py','--output','runs/episode-boundary-v011-final'],
 'pytest':['-m','pytest','-q'],
 'ruff':['-m','ruff','check','src','tests','scripts'],
 'reward':['scripts/reward_contract_experiment_v011.py','--output','runs/reward-contract-v011-final','--executable-episode','runs/executable-projects-v11-final/tests_tampered/episode'],
 'A2':['scripts/model_development_experiment.py','--protocol','examples/model-v11/two-workers-protocol.json','--output','runs/model-two-workers-v11-final','--workers','1'],
 'Bmodel':['scripts/model_development_experiment.py','--protocol','examples/model-v11/project-pilot-protocol.json','--output','runs/model-public-projects-v11-final','--workers','2'],
}
def now():return datetime.now(timezone.utc).isoformat()
def inputs():
 paths={Path('pyproject.toml')}
 for base in ['tests','scripts','examples']:
  paths.update(p for p in Path(base).rglob('*') if p.is_file() and '__pycache__' not in p.parts)
 return {str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(paths)}
report={'source_before':code_identity(),'input_sha256_before':inputs(),'started_at':now(),'jobs':[],
        'resources':{'cpu_count':os.cpu_count(),'parallel_jobs':4,'A1_parallel_worlds':6,'qwen_physical_gpu':7,'model_service':'runs/qwen-service-v11/service.json','weights':'runs/model-api-v11-preflight/qwen-weights.json','shared_gpu':True,'one_writer_per_world':True},
        'scope':'First v011 freeze:36one-model development episodes; separate 2model-role and public-project pilots; mechanism/episode/reward and fullregression. RL is a later separate freeze.'}
assert not report['source_before']['code_dirty']
def job(name):
 before=code_identity();start=now();log=Path('/tmp/proworksim-v011-a-'+name+'.log')
 with log.open('w') as out:r=subprocess.run([PYTHON]+JOBS[name],stdout=out,stderr=subprocess.STDOUT)
 result={'group':name,'command':[PYTHON]+JOBS[name],'source_before':before,'source_after':code_identity(),'started_at':start,'ended_at':now(),'exit_code':r.returncode,'log':str(log),'log_sha256':hashlib.sha256(log.read_bytes()).hexdigest()}
 print(json.dumps(result),flush=True);return result
with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
 futures={pool.submit(job,name):name for name in ['A1','B','conditions','episode','pytest','ruff']}
 while futures:
  done,_=concurrent.futures.wait(futures,return_when=concurrent.futures.FIRST_COMPLETED)
  for future in done:
   name=futures.pop(future);result=future.result();report['jobs'].append(result)
   Path('/tmp/proworksim-v011-a-progress.json').write_text(json.dumps(report,indent=2)+'\n')
   if name=='B': futures[pool.submit(job,'reward')]='reward'
   if name=='A1':
    for later in ['A2','Bmodel']:futures[pool.submit(job,later)]=later
report.update(source_after=code_identity(),input_sha256_after=inputs(),ended_at=now())
Path('/tmp/proworksim-v011-a-supervisor.json').write_text(json.dumps(report,indent=2)+'\n')
assert report['source_before']==report['source_after'] and report['input_sha256_before']==report['input_sha256_after']
raise SystemExit(0 if all(j['exit_code']==0 for j in report['jobs']) else 1)

